package main

import (
	"fmt"
	"time"
)

func main() {
	// 创建两个channel
	ch1 := make(chan string)
	ch2 := make(chan string)

	// 启动两个goroutine模拟不同时间的操作
	go func() {
		time.Sleep(1 * time.Second)
		ch1 <- "来自ch1的消息"
	}()

	go func() {
		time.Sleep(2 * time.Second)
		ch2 <- "来自ch2的消息"
	}()

	// 使用select等待两个channel，设置3秒超时
	select {
	case msg := <-ch1:
		fmt.Printf("收到消息: %s\n", msg)
	case msg := <-ch2:
		fmt.Printf("收到消息: %s\n", msg)
	case <-time.After(3 * time.Second):
		fmt.Println("操作超时，等待了3秒")
	}

	// 使用select实现非阻塞的channel操作
	nonBlockingCheck := func(ch chan string) {
		select {
		case msg, ok := <-ch:
			if ok {
				fmt.Printf("收到消息: %s\n", msg)
			} else {
				fmt.Println("channel已关闭")
			}
		default:
			fmt.Println("channel中没有消息")
		}
	}

	// 测试非阻塞检查
	testCh := make(chan string, 1)
	testCh <- "测试消息"
	nonBlockingCheck(testCh)
	nonBlockingCheck(testCh)

	close(testCh)
	nonBlockingCheck(testCh)

	// 使用select监听多个channel并实现数据聚合
	results := make(chan int, 3)
	for i := 0; i < 3; i++ {
		go func(id int) {
			time.Sleep(time.Duration(id+1) * 500 * time.Millisecond)
			results <- id * 10
		}(i)
	}

	// 收集所有结果
	total := 0
	for i := 0; i < 3; i++ {
		select {
		case result := <-results:
			fmt.Printf("收到结果: %d\n", result)
			total += result
			fmt.Printf("当前总计: %d\n", total)
		}
	}

	fmt.Printf("最终总计: %d\n", total)
}

